/* Demonstracao local independente. Nao possui autenticacao real e nao substitui a API Java. */
'use strict';
const $=(s)=>document.querySelector(s);
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ic=(name)=>`<ui-icon><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${ICON_PATHS[name]||ICON_PATHS.ticket}"/></svg></ui-icon>`;
const LABEL={ABERTO:'Aberto',EM_ANDAMENTO:'Em andamento',AGUARDANDO_USUARIO:'Aguardando usuário',AGUARDANDO_TERCEIROS:'Aguardando terceiros',RESOLVIDO:'Resolvido',FECHADO:'Encerrado',CANCELADO:'Cancelado'};
const PL={BAIXA:'Baixa',MEDIA:'Média',ALTA:'Alta',CRITICA:'Crítica'},RL={ADMIN:'Administrador',TECNICO:'Técnico de TI',COLABORADOR:'Colaborador'};
const HOURS={BAIXA:72,MEDIA:24,ALTA:8,CRITICA:4};
const TRANS={ABERTO:['EM_ANDAMENTO','CANCELADO'],EM_ANDAMENTO:['AGUARDANDO_USUARIO','AGUARDANDO_TERCEIROS','RESOLVIDO','CANCELADO'],AGUARDANDO_USUARIO:['EM_ANDAMENTO','RESOLVIDO','CANCELADO'],AGUARDANDO_TERCEIROS:['EM_ANDAMENTO','RESOLVIDO','CANCELADO'],RESOLVIDO:['FECHADO','EM_ANDAMENTO'],FECHADO:['EM_ANDAMENTO'],CANCELADO:[]};
const DEPARTMENTS=['Recepção','Diretoria','Cobrança','Assistentes','RH','Telefonista','Jurídico','Financeiro','Compras','Contabilidade','Conferência','Tecnologia da Informação'];
const CATEGORIES=['Computadores','Rede e internet','Impressoras','Sistemas e acessos','E-mail e comunicação','Instalação de software','Telefonia','Outros'];
const PAGES={dashboard:['Visão geral','Um panorama do suporte. Tudo no seu controle.','dashboard'],tickets:['Central de chamados','Cada solicitação, uma solução. Acompanhe de perto.','ticket'],board:['Quadro de atendimento','Organize o fluxo de trabalho da equipe de TI.','board'],departments:['Departamentos','Todos os setores conectados ao mesmo suporte.','department'],knowledge:['Base de conhecimento','Respostas que ajudam. Conhecimento que simplifica.','book'],reports:['Relatórios e indicadores','Transforme os dados do atendimento em boas decisões.','chart'],users:['Pessoas e acessos','As pessoas certas, com as permissões certas.','users'],settings:['Configurações','Sua conta, preferências e organização.','settings'],assistant:['Assistente de suporte','Vamos encontrar o melhor caminho para resolver seu problema.','bolt']};
const INITIAL_ARTICLES=[
 ['Primeiros passos no Chamado Rápido','Aprenda a pedir ajuda, acompanhar respostas e avaliar seu atendimento.','Primeiros passos','1. Escolha Novo chamado ou use o Assistente.\n\n2. Informe o problema com um título objetivo.\n\n3. Descreva quando começou, o que já tentou e o impacto no trabalho.\n\n4. Anexe uma captura sem dados pessoais ou senhas.\n\n5. Acompanhe a conversa e as atualizações em Meus chamados.\n\n6. Após a solução, confirme o encerramento e avalie o atendimento.'],
 ['Minha internet parou. O que verificar?','Faça verificações simples e seguras antes de pedir ajuda.','Rede e internet','Verifique se outros colegas enfrentam o mesmo problema. Confira apenas o encaixe do cabo externo de rede ou a conexão Wi-Fi.\n\nNão reinicie roteadores corporativos, switches ou servidores.\n\nSe a internet estiver totalmente indisponível, use outro dispositivo conectado ou o canal alternativo de TI da empresa. Informe o setor e os equipamentos afetados.'],
 ['Impressora não imprime','Confira a impressora selecionada e registre a mensagem do visor.','Impressoras','Confira se selecionou a impressora correta e se há papel na bandeja.\n\nAnote a mensagem de erro exibida. Não desmonte o equipamento nem cancele trabalhos de outras pessoas.\n\nSe persistir, abra um chamado com o nome da impressora e uma foto do erro, sem expor documentos.'],
 ['Como escrever um bom chamado','Um relato completo ajuda a equipe de TI a agir com mais agilidade.','Boas práticas','Seja específico: "Não consigo entrar no sistema de cobrança" é melhor do que "Urgente".\n\nDescreva o resultado esperado e o que aparece na tela. Informe a localização, o equipamento e o ramal.\n\nNão compartilhe senhas ou informações de clientes. Informe quantas pessoas estão afetadas.'],
 ['Proteja suas credenciais','Saiba o que nunca enviar em um chamado ou na conversa com o assistente.','Segurança','A equipe de TI não precisa saber sua senha.\n\nNão envie códigos de autenticação, certificados digitais ou documentos de clientes.\n\nDesconfie de links inesperados. Oculte informações pessoais em capturas de tela antes de anexá-las.'],
 ['Entenda as prioridades e prazos','Veja como a prioridade ajuda a organizar o atendimento.','Atendimento','Crítica: atividade essencial interrompida para várias pessoas (4 horas).\n\nAlta: trabalho impedido sem alternativa (8 horas).\n\nMédia: problema parcial ou com alternativa (24 horas).\n\nBaixa: melhoria sem interrupção (72 horas).\n\nSão metas em horas corridas, não promessas contratuais. A espera pelo usuário ou terceiros não pausa o prazo.']
];
function seed(){
 const people=['Ana Martins','Daniel Costa','Juliana Santos','Rafael Lima','Camila Ferreira','Beatriz Oliveira','Marcos Ribeiro','Luiza Almeida','Bruno Souza','Patrícia Mendes','Felipe Rocha'];
 const emails=['recepcao','diretoria','cobranca','assistentes','rh','telefonista','juridico','financeiro','compras','contabilidade','conferencia'];
 const users=[{id:1,name:'Administrador',email:'admin@chamadorapido.local',role:'ADMIN',departmentId:12,active:true},{id:2,name:'Equipe de TI',email:'ti@chamadorapido.local',role:'TECNICO',departmentId:12,active:true},...people.map((name,i)=>({id:i+3,name,email:emails[i]+'@chamadorapido.local',role:'COLABORADOR',departmentId:i+1,active:true}))];
 const titles=['Impressora não imprime os documentos','Sem acesso ao sistema financeiro','Computador reiniciando durante o uso','Configurar e-mail no novo computador','Internet instável no departamento','Instalação de leitor de PDF','Monitor sem imagem na estação','Ramal sem receber ligações','Acesso à pasta compartilhada','Planilha não abre no computador','Atualização do sistema de cobrança','Configuração de impressora de etiquetas'];
 const cat=[3,4,1,5,2,6,1,7,4,1,4,3];const tickets=[];
 for(let i=0;i<36;i++){const requester=users[i%11+2];const priority=['MEDIA','CRITICA','ALTA','BAIXA'][i%4];const state=i%9;const status=state<2?'ABERTO':state<5?'EM_ANDAMENTO':state===5?'AGUARDANDO_USUARIO':state===6?'AGUARDANDO_TERCEIROS':state===7?'RESOLVIDO':'FECHADO';const createdAt=new Date(Date.now()-(i*5+1)*3600000).toISOString();const solved=['RESOLVIDO','FECHADO'].includes(status);const resolvedAt=solved?new Date(Date.parse(createdAt)+3*3600000).toISOString():null;
 tickets.push({id:36-i,title:titles[i%12],description:'Solicito apoio da equipe de TI. '+titles[i%12]+'. O problema está dificultando as atividades do setor. Já conferimos os procedimentos básicos.\n\nDados fictícios para demonstração.',requesterId:requester.id,departmentId:requester.departmentId,categoryId:cat[i%12],priority,status,assigneeId:state<2?null:(i%2===0?1:2),createdAt,updatedAt:resolvedAt||createdAt,dueAt:new Date(Date.parse(createdAt)+HOURS[priority]*3600000).toISOString(),resolvedAt,solution:solved?'Configuração revisada e testes realizados com o solicitante. Funcionamento normalizado.':'',rating:solved?(i%2?4:5):null,location:'Estação '+(i%8+1)+' - '+DEPARTMENTS[requester.departmentId-1],equipment:'PC-'+String(i+1).padStart(3,'0'),contact:'Ramal '+(200+i),comments:state<2?[]:[{authorId:2,body:'Recebemos sua solicitação. Estamos verificando o equipamento e acompanharemos o caso por aqui.',internal:false,createdAt}],history:[{action:'Chamado aberto',details:'Solicitação registrada para '+DEPARTMENTS[requester.departmentId-1],actor:requester.name,createdAt}],attachments:[]});}
 return {version:1,userId:1,users,departments:DEPARTMENTS.map((name,i)=>({id:i+1,name,active:true})),categories:CATEGORIES.map((name,i)=>({id:i+1,name,active:true})),tickets,articles:INITIAL_ARTICLES.map((a,i)=>({id:i+1,title:a[0],excerpt:a[1],category:a[2],body:a[3],active:true,updatedAt:new Date().toISOString()})),readNotices:[],theme:'light'};
}
let S;try{S=JSON.parse(localStorage.getItem('chamado-rapido-demo-v1')||'null')||seed();if(S.version!==1)S=seed();}catch{S=seed();}
let view=PAGES[location.hash.slice(1)]?location.hash.slice(1):'dashboard',filter={q:'',status:'',priority:'',department:'',overdue:false,mine:false},page=0,range=30,detailId=null,detailTab='conversation',articleQuery='',articleCategory='',userQuery='',triage=null,toastTimer;
const current=()=>S.users.find(u=>u.id===S.userId)||S.users[0],staff=()=>current().role!=='COLABORADOR',admin=()=>current().role==='ADMIN';
const user=(id)=>S.users.find(u=>u.id===Number(id)),dept=(id)=>S.departments.find(d=>d.id===Number(id))?.name||'Departamento',cat=(id)=>S.categories.find(c=>c.id===Number(id))?.name||'Categoria';
const initial=(name)=>String(name).split(' ').filter(Boolean).slice(0,2).map(n=>n[0]).join('').toUpperCase();
const avatar=(name,type='')=>`<span class="avatar ${type}">${esc(initial(name))}</span>`;
const protocol=(t)=>'CR-'+String(t.id).padStart(6,'0');
const terminal=(t)=>['RESOLVIDO','FECHADO','CANCELADO'].includes(t.status);
const late=(t)=>!terminal(t)&&Date.parse(t.dueAt)<Date.now();
const date=(value)=>new Date(value).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'});
const relative=(value)=>{let m=Math.max(0,Math.floor((Date.now()-Date.parse(value))/60000));return m<1?'Agora':m<60?'Há '+m+' min':m<1440?'Há '+Math.floor(m/60)+' h':'Há '+Math.floor(m/1440)+' dias';};
const deadline=(t)=>{if(terminal(t))return 'Finalizado';const h=Math.round((Date.parse(t.dueAt)-Date.now())/3600000);return h<0?'Atrasado '+Math.abs(h)+' h':'Restam '+h+' h';};
const visible=()=>S.tickets.filter(t=>staff()||t.requesterId===current().id).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));
function filtered(){const q=filter.q.toLocaleLowerCase().trim();return visible().filter(t=>(!q||(t.title+' '+protocol(t)+' '+dept(t.departmentId)+' '+user(t.requesterId).name).toLocaleLowerCase().includes(q))&&(!filter.status||t.status===filter.status)&&(!filter.priority||t.priority===filter.priority)&&(!filter.department||t.departmentId===Number(filter.department))&&(!filter.overdue||late(t))&&(!filter.mine||(staff()?t.assigneeId===current().id:t.requesterId===current().id)));}
function persist(){try{localStorage.setItem('chamado-rapido-demo-v1',JSON.stringify(S));}catch{setTimeout(()=>notify('O armazenamento do navegador está cheio. As alterações permanecem apenas nesta sessão.',true),100);}}
function notify(text,error=false){clearTimeout(toastTimer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${ic(error?'alert':'checkCircle')}<span>${esc(text)}</span><button class="icon-button" onclick="this.closest('.toast').remove()" aria-label="Fechar aviso">${ic('close')}</button></div>`;toastTimer=setTimeout(()=>$('#toast-root').innerHTML='',6500);}
function navigate(next){if(!PAGES[next])return;if(!staff()&&['board','departments','reports','users'].includes(next))return;if(!admin()&&next==='users')return;view=next;location.hash=next;render();window.scrollTo(0,0);}
function nav(next,label,extra=''){return `<button class="${view===next?'active':''}" onclick="navigate('${next}')">${ic(PAGES[next][2])}${label||PAGES[next][0]}${extra}</button>`;}
function status(t){return `<span class="status-badge" data-status="${t.status}"><i></i>${LABEL[t.status]}</span>`;}
function priority(t){return `<span class="priority" data-priority="${t.priority}"><i></i>${PL[t.priority]}</span>`;}
function selectOptions(entries,value,placeholder){return (placeholder?`<option value="">${placeholder}</option>`:'')+entries.map(([key,label])=>`<option value="${esc(key)}" ${String(value)===String(key)?'selected':''}>${esc(label)}</option>`).join('');}
function summaries(){const all=visible().filter(t=>!range||Date.parse(t.createdAt)>=Date.now()-range*86400000),solved=all.filter(t=>t.resolvedAt&&t.status!=='CANCELADO');const ratings=all.filter(t=>t.rating);const daily=[];for(let i=6;i>=0;i--){const day=new Date();day.setDate(day.getDate()-i);const key=day.toDateString();daily.push({day:day.toLocaleDateString('pt-BR',{weekday:'short'}).replace('.',''),created:all.filter(t=>new Date(t.createdAt).toDateString()===key).length,resolved:solved.filter(t=>new Date(t.resolvedAt).toDateString()===key).length});}return {all,total:all.length,active:all.filter(t=>!terminal(t)).length,resolved:solved.length,overdue:all.filter(late).length,sla:solved.length?Math.round(100*solved.filter(t=>Date.parse(t.resolvedAt)<=Date.parse(t.dueAt)).length/solved.length):null,average:solved.length?(solved.reduce((v,t)=>v+(Date.parse(t.resolvedAt)-Date.parse(t.createdAt))/3600000,0)/solved.length).toFixed(1):null,rating:ratings.length?(ratings.reduce((n,t)=>n+t.rating,0)/ratings.length).toFixed(1):null,daily,byStatus:Object.keys(LABEL).map(s=>({status:s,count:all.filter(t=>t.status===s).length}))};}
function heading(){const p=PAGES[view];let actions='';if(['dashboard','reports'].includes(view))actions+=`<select aria-label="Período dos indicadores" onchange="range=Number(this.value);render()">${selectOptions([[7,'Últimos 7 dias'],[30,'Últimos 30 dias'],[90,'Últimos 90 dias'],[0,'Todo o período']],range)}</select>`;actions+=view==='users'?`<button class="btn primary" onclick="editUser()">${ic('plus')}Adicionar pessoa</button>`:view==='knowledge'&&admin()?`<button class="btn primary" onclick="editArticle()">${ic('plus')}Novo artigo</button>`:view==='reports'?`<button class="btn primary" onclick="exportReport()">${ic('download')}Exportar CSV</button>`:`<button class="btn primary" onclick="newTicket()">${ic('plus')}Novo chamado</button>`;return `<div class="page-heading"><div><span class="eyebrow">${view==='dashboard'?'CENTRAL DE SERVIÇOS DE TI':'CHAMADO RÁPIDO'}</span><h1>${view==='dashboard'?'Olá, '+esc(current().name.split(' ')[0])+'. Vamos simplificar?':p[0]}</h1><p>${p[1]}</p></div><div class="page-actions">${actions}</div></div>`;}
function render(){
 if(!staff()&&['board','departments','reports','users'].includes(view))view='dashboard';if(!admin()&&view==='users')view='dashboard';document.documentElement.dataset.theme=S.theme;
 const u=current(),m=summaries(),unread=visible().slice(0,5).filter(t=>!S.readNotices.includes(t.id)).length;
 $('#app').innerHTML=`<div class="app-shell"><aside class="sidebar"><a class="brand-card" href="#dashboard" onclick="navigate('dashboard')"><img src="assets/logo.png" alt="Chamado Rápido"></a><div class="workspace-tag"><span class="workspace-mark">TI</span><div><strong>Central de serviços</strong><small>Workspace corporativo</small></div><span class="live-dot"></span></div><nav aria-label="Navegação principal"><span class="nav-label">PRINCIPAL</span>${nav('dashboard','Visão geral')}${nav('tickets',staff()?'Chamados':'Meus chamados',`<span class="nav-count">${m.active}</span>`)}${staff()?nav('board'):''}${nav('assistant','Assistente','<span class="mini-tag">RÁPIDO</span>')}${nav('knowledge')}${staff()?'<span class="nav-label">GESTÃO</span>'+nav('departments')+nav('reports'):''}${admin()?nav('users'):''}${nav('settings')}</nav><div class="sidebar-help"><span class="help-symbol">${ic('chat')}</span><strong>Uma ajuda antes do chamado?</strong><p>Nosso assistente pode encontrar a solução com você.</p><button onclick="navigate('assistant')">Conversar agora${ic('arrow')}</button></div><div class="sidebar-user">${avatar(u.name,'yellow')}<div><strong>${esc(u.name)}</strong><small>${RL[u.role]}</small></div><button class="icon-button" onclick="switchProfile()" title="Simular outro perfil" aria-label="Trocar perfil da demonstração">${ic('logout')}</button></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><button class="icon-button mobile-only" onclick="toggleMobile()" aria-label="Abrir menu">${ic('menu')}</button><span>Workspace</span>${ic('chevron')}<strong>${PAGES[view][0]}</strong></div><div class="topbar-actions"><form class="global-search" onsubmit="event.preventDefault();filter.q=this.querySelector('input').value;page=0;navigate('tickets')">${ic('search')}<input placeholder="Buscar um chamado..." value="${esc(filter.q)}" aria-label="Buscar chamado"><kbd>↵</kbd></form><button class="icon-button" onclick="toggleTheme()" title="Alternar tema" aria-label="Alternar tema">${ic(S.theme==='light'?'moon':'sun')}</button><div class="notifications-container"><button class="icon-button notification-trigger ${unread?'has-unread':''}" onclick="toggleNotices()" aria-label="Notificações">${ic('bell')}</button><div id="notices"></div></div><span class="topbar-divider"></span><button class="avatar navy" onclick="navigate('settings')" aria-label="Minha conta">${initial(u.name)}</button></div></header><div class="demo-banner"><span></span> Demonstração local <b>Dados fictícios neste navegador · Sem servidor ou autenticação</b></div><main class="main-content">${heading()}${pageContent()}<footer class="workspace-footer"><span>Chamado Rápido <b>·</b> Tecnologia que simplifica, suporte que resolve.</span><span>Central de TI <b>·</b> v1.0</span></footer></main></div></div>`;
}
function toggleMobile(){const side=$('.sidebar');side.classList.toggle('open');const old=$('.sidebar-scrim');if(old)old.remove();else if(side.classList.contains('open')){const b=document.createElement('button');b.className='sidebar-scrim';b.ariaLabel='Fechar menu';b.onclick=toggleMobile;document.body.appendChild(b);}}
function toggleTheme(){S.theme=S.theme==='light'?'dark':'light';persist();render();}
function stat(label,value,note,icon,color){return `<section class="stat-card">${icon?`<span class="stat-icon ${color}">${ic(icon)}</span>`:''}<span class="stat-label">${label}</span><strong>${value??'—'}</strong><small>${note}</small></section>`;}
function table(items){return `<div class="table-wrap"><table class="ticket-table"><thead><tr><th>Chamado</th><th>Departamento</th><th>Prioridade</th><th>Status</th><th>Prazo</th><th>Responsável</th><th></th></tr></thead><tbody>${items.length?items.map(t=>`<tr onclick="openTicket(${t.id})"><td><button class="ticket-title" onclick="event.stopPropagation();openTicket(${t.id})"><small>${protocol(t)} <span>· ${relative(t.createdAt)}</span></small><strong>${esc(t.title)}</strong></button></td><td><span class="department-name">${esc(dept(t.departmentId))}</span></td><td>${priority(t)}</td><td>${status(t)}</td><td><span class="deadline ${late(t)?'danger':''}">${ic(terminal(t)?'checkCircle':'clock')}${deadline(t)}</span></td><td><span class="assignee">${t.assigneeId?avatar(user(t.assigneeId)?.name||'TI','tiny')+esc(user(t.assigneeId)?.name.split(' ')[0]||'TI'):'<span class="unassigned">Não atribuído</span>'}</span></td><td>${ic('chevron')}</td></tr>`).join(''):`<tr><td colspan="7"><div class="empty"><span class="empty-symbol">${ic('ticket')}</span><h3>Nenhum chamado por aqui.</h3><p>Crie sua primeira solicitação ou ajuste os filtros.</p><button class="btn primary" onclick="newTicket()">${ic('plus')}Novo chamado</button></div></td></tr>`}</tbody></table></div>`;}
function chart(m){const max=Math.max(1,...m.daily.flatMap(d=>[d.created,d.resolved]));const path=key=>m.daily.map((d,i)=>`${i?'L':'M'} ${35+i*92} ${166-d[key]/max*130}`).join(' ');return `<section class="panel activity-panel"><div class="panel-title"><div><h2>Movimentação dos chamados</h2><p>Uma semana de conexões e soluções.</p></div><div class="chart-legend"><span><i class="legend-line navy-line"></i>Abertos</span><span><i class="legend-line gold-line"></i>Resolvidos</span></div></div><div class="line-chart"><svg viewBox="0 0 630 212" role="img" aria-label="Aberturas e resoluções dos últimos sete dias"><defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#102A43" stop-opacity=".12"/><stop offset="100%" stop-color="#102A43" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<line x1="35" x2="600" y1="${36+i*43}" y2="${36+i*43}" class="chart-gridline"/><text x="7" y="${40+i*43}">${Math.round((3-i)*max/3)}</text>`).join('')}<path d="${path('created')} L 587 180 L 35 180 Z" fill="url(#areaGradient)"/><path d="${path('created')}" class="chart-line chart-primary"/><path d="${path('resolved')}" class="chart-line chart-secondary"/>${m.daily.map((d,i)=>`<circle cx="${35+i*92}" cy="${166-d.created/max*130}" r="4" class="chart-dot"><title>${d.created} abertos</title></circle><text x="${35+i*92}" y="203" text-anchor="middle">${d.day}</text>`).join('')}</svg></div></section>`;}
function donut(m){const colors={ABERTO:'#517baf',EM_ANDAMENTO:'#e6b316',AGUARDANDO_USUARIO:'#a48acb',AGUARDANDO_TERCEIROS:'#c389a9',RESOLVIDO:'#4ba886',FECHADO:'#42705f',CANCELADO:'#a8b3bd'};let start=0;const stops=m.byStatus.filter(s=>s.count).map(s=>{const end=start+s.count/m.total*100;let str=colors[s.status]+' '+start+'% '+end+'%';start=end;return str;});return `<section class="panel distribution-panel"><div class="panel-title"><h2>Chamados por status</h2>${ic('chart')}</div><div class="donut" style="background:${m.total?'conic-gradient('+stops.join(',')+')':'var(--line)'}"><div><strong>${m.total}</strong><small>no período</small></div></div><div class="status-legend">${m.byStatus.filter(s=>s.count).map(s=>`<div><span><i class="tiny-dot" data-status="${s.status}"></i>${LABEL[s.status]}</span><strong>${s.count}</strong></div>`).join('')}</div></section>`;}
function dashboard(){const m=summaries();return `<section class="welcome-banner"><div><span class="banner-tag">${ic('bolt')} SUPORTE NO SEU RITMO</span><h2>Seu dia com menos interrupções.</h2><p>Conte com a tecnologia. Conte com a nossa equipe.</p></div><button class="btn banner-button" onclick="navigate('assistant')">Encontrar uma solução${ic('arrow')}</button><img class="banner-mascot" src="assets/mascote.png" alt=""></section><div class="stats-grid">${stat('Chamados no período',m.total,'Solicitações registradas','ticket','blue')}${stat('Em aberto',m.active,'<span class="tiny-dot yellow-dot"></span>Em atendimento ou na fila','clock','gold')}${stat('Resolvidos',m.resolved,'Soluções que fazem a diferença','checkCircle','green')}${stat('Dentro do prazo',m.sla===null?'—':m.sla+'%','Entre os chamados resolvidos','shield','purple')}</div><div class="dashboard-grid">${chart(m)}${donut(m)}</div>${m.overdue?`<button class="attention-strip" onclick="filter.overdue=true;page=0;navigate('tickets')"><span class="attention-icon">${ic('alert')}</span><div><strong>${m.overdue} chamado(s) precisam de atenção</strong><span>O prazo definido foi ultrapassado. Vamos dar o próximo passo?</span></div><span class="attention-link">Ver chamados${ic('arrow')}</span></button>`:''}<section class="panel recent-panel"><div class="panel-title"><div><h2>Chamados recentes</h2><p>As últimas solicitações, em um só lugar.</p></div><button class="text-button" onclick="navigate('tickets')">Ver todos${ic('arrow')}</button></div>${table(visible().slice(0,5))}</section>`;}
function applyFilters(event){event.preventDefault();const f=new FormData(event.target);filter.q=String(f.get('q')||'');filter.status=String(f.get('status')||'');filter.priority=String(f.get('priority')||'');filter.department=String(f.get('department')||'');page=0;render();}
function resetFilters(){filter={q:'',status:'',priority:'',department:'',overdue:false,mine:false};page=0;render();}
function filtersPanel(){return `<section class="panel"><div class="tabs-row"><button class="${!filter.mine?'active':''}" onclick="filter.mine=false;page=0;render()">${staff()?'Todos os chamados':'Meus chamados'}<span class="count">${filtered().length}</span></button>${staff()?`<button class="${filter.mine?'active':''}" onclick="filter.mine=true;page=0;render()">Atribuídos a mim</button>`:''}<div class="view-switch"><button class="${view==='tickets'?'selected':''}" onclick="navigate('tickets')" aria-label="Lista">${ic('ticket')}</button>${staff()?`<button class="${view==='board'?'selected':''}" onclick="navigate('board')" aria-label="Quadro">${ic('board')}</button>`:''}</div></div><form class="filters" onsubmit="applyFilters(event)"><div class="input-icon filter-search">${ic('search')}<input name="q" value="${esc(filter.q)}" placeholder="Título, solicitante ou CR-000001" aria-label="Pesquisar chamados"></div><select name="status" onchange="this.form.requestSubmit()" aria-label="Filtrar status">${selectOptions(Object.entries(LABEL),filter.status,'Todos os status')}</select><select name="priority" onchange="this.form.requestSubmit()" aria-label="Filtrar prioridade">${selectOptions(Object.entries(PL),filter.priority,'Prioridades')}</select>${staff()?`<select name="department" onchange="this.form.requestSubmit()" aria-label="Filtrar departamento">${selectOptions(S.departments.map(d=>[d.id,d.name]),filter.department,'Departamentos')}</select>`:''}<button class="btn secondary compact" type="submit">${ic('filter')}Filtrar</button><button class="icon-button" type="button" onclick="resetFilters()" title="Limpar filtros" aria-label="Limpar filtros">${ic('refresh')}</button></form>${filter.overdue?`<div class="active-filter">Exibindo chamados fora do prazo<button onclick="filter.overdue=false;render()" aria-label="Remover filtro de atraso">${ic('close')}</button></div>`:''}`;}
function ticketsPage(){const list=filtered(),pages=Math.max(1,Math.ceil(list.length/12));page=Math.min(page,pages-1);return filtersPanel()+table(list.slice(page*12,page*12+12))+`<footer class="pagination"><span>${list.length} chamado(s) encontrado(s)</span><div><button class="btn secondary compact" onclick="page--;render()" ${page===0?'disabled':''}>Anterior</button><span>Página ${page+1} de ${pages}</span><button class="btn secondary compact" onclick="page++;render()" ${page+1>=pages?'disabled':''}>Próxima</button></div></footer></section>`;}
function boardPage(){return filtersPanel()+`</section><p class="board-note">${ic('info')}Arraste para propor uma mudança e confirme no chamado.</p><div class="kanban">${[['ABERTO','Na fila','blue'],['EM_ANDAMENTO','Em atendimento','yellow'],['AGUARDANDO_USUARIO','Aguardando','purple'],['RESOLVIDO','Resolvidos','green']].map(([id,title,color])=>{const items=filtered().filter(t=>id==='AGUARDANDO_USUARIO'?t.status.startsWith('AGUARDANDO'):id==='RESOLVIDO'?['RESOLVIDO','FECHADO'].includes(t.status):t.status===id);return `<section class="kanban-column" ondragover="event.preventDefault()" ondrop="dropTicket(event,'${id}')"><header><span class="tiny-dot ${color}-dot"></span><strong>${title}</strong><span class="count">${items.length}</span></header>${items.map(t=>`<button class="kanban-card" draggable="true" ondragstart="event.dataTransfer.setData('text/plain','${t.id}')" onclick="openTicket(${t.id})"><div class="kanban-meta"><span>${protocol(t)}</span>${priority(t)}</div><h3>${esc(t.title)}</h3><p>${esc(dept(t.departmentId))}</p><footer>${avatar(user(t.requesterId).name,'tiny')}<span class="${late(t)?'danger':''}">${ic('clock')}${deadline(t)}</span></footer></button>`).join('')||'<div class="kanban-empty">Nenhum chamado nesta etapa.</div>'}</section>`;}).join('')}</div>`;}
function dropTicket(e,status){e.preventDefault();const id=Number(e.dataTransfer.getData('text/plain'));openTicket(id);const select=$('#edit-status');if(select&&[...select.options].some(o=>o.value===status)){select.value=status;detailFields();notify('Confirme a alteração no painel do chamado.');}else notify('Essa transição não é permitida.',true);}
function departmentsPage(){return `<div class="section-intro"><p><strong>${S.departments.length-1}</strong> setores solicitantes e uma equipe de TI conectada a todos eles.</p>${admin()?`<button class="btn secondary" onclick="editCatalog('departments')">${ic('plus')}Adicionar setor</button>`:''}</div><div class="department-grid">${S.departments.map(d=>{let ts=S.tickets.filter(t=>t.departmentId===d.id);return `<section class="department-card"><div class="department-top"><span class="department-icon">${ic('department')}</span><span class="badge ${d.active?'':'inactive'}">${d.active?'Ativo':'Inativo'}</span></div><h2>${esc(d.name)}</h2><p>Conectado à central de TI</p><div class="department-metrics"><div><strong>${ts.length}</strong><span>Chamados</span></div><div><strong>${ts.filter(t=>!terminal(t)).length}</strong><span>Em aberto</span></div><div><strong class="${ts.some(late)?'danger':''}">${ts.filter(late).length}</strong><span>Em atraso</span></div></div><footer><button class="text-button" onclick="filter={q:'',status:'',priority:'',department:'${d.id}',overdue:false,mine:false};page=0;navigate('tickets')">Ver chamados${ic('arrow')}</button>${admin()?`<button class="icon-button" onclick="editCatalog('departments',${d.id})" aria-label="Editar ${esc(d.name)}">${ic('edit')}</button>`:''}</footer></section>`;}).join('')}</div>`;}
function knowledgePage(){return `<section class="knowledge-hero"><span class="knowledge-icon">${ic('book')}</span><h2>Uma boa resposta pode mudar seu dia.</h2><p>Encontre orientações antes de abrir um chamado.</p><form class="input-icon" onsubmit="event.preventDefault();articleQuery=this.querySelector('input').value;render()">${ic('search')}<input value="${esc(articleQuery)}" oninput="articleQuery=this.value;renderArticleList()" placeholder="Busque por internet, impressora, acesso..." aria-label="Pesquisar artigos"></form></section><div class="category-pills"><button class="${!articleCategory?'selected':''}" onclick="articleCategory='';render()">Todos os artigos</button>${[...new Set(S.articles.map(a=>a.category))].map(c=>`<button class="${articleCategory===c?'selected':''}" data-category="${esc(c)}" onclick="articleCategory=this.dataset.category;render()">${esc(c)}</button>`).join('')}</div><div class="article-grid" id="article-list">${articleList()}</div>`;}
function articleList(){return S.articles.filter(a=>(a.active||admin())&&(!articleCategory||a.category===articleCategory)&&(a.title+' '+a.excerpt+' '+a.body).toLocaleLowerCase().includes(articleQuery.toLocaleLowerCase())).map(a=>`<button class="article-card" onclick="openArticle(${a.id})"><div><span class="article-icon">${ic('file')}</span><span class="article-category">${esc(a.category)}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.excerpt)}</p><footer><span>${a.active?'Leitura rápida':'Rascunho / inativo'}</span><span>Ler artigo${ic('arrow')}</span></footer></button>`).join('')||`<div class="empty">${ic('search')}<h3>Nenhum artigo encontrado.</h3><p>Tente outra palavra.</p></div>`;}
function renderArticleList(){if($('#article-list'))$('#article-list').innerHTML=articleList();}
function reportsPage(){const m=summaries();return `<div class="stats-grid">${stat('Total no período',m.total,'Chamados registrados')}${stat('Tempo médio de solução',m.average?m.average+' h':'—','Da abertura à resolução')}${stat('Resoluções dentro do prazo',m.sla===null?'—':m.sla+'%',m.resolved+' chamados resolvidos')}${stat('Satisfação',(m.rating||'—')+'<small>/ 5</small>','Avaliações dos solicitantes')}</div><section class="panel report-panel"><div class="panel-title"><div><h2>Distribuição por status</h2><p>Chamados abertos no período selecionado.</p></div></div><div class="report-bars">${m.byStatus.map(s=>`<div><span>${LABEL[s.status]}</span><div class="progress-track"><i style="width:${m.total?s.count/m.total*100:0}%" data-status="${s.status}"></i></div><strong>${s.count}</strong></div>`).join('')}</div></section><section class="panel report-panel"><div class="panel-title"><div><h2>Volume por departamento</h2><p>Visão acumulada de todo o período.</p></div><span class="badge">${S.departments.length} departamentos</span></div><div class="table-wrap"><table><thead><tr><th>Departamento</th><th>Total</th><th>Em aberto</th><th>Fora do prazo</th></tr></thead><tbody>${S.departments.map(d=>{let ts=S.tickets.filter(t=>t.departmentId===d.id);return `<tr><td><strong>${esc(d.name)}</strong></td><td>${ts.length}</td><td>${ts.filter(t=>!terminal(t)).length}</td><td class="${ts.some(late)?'danger':''}">${ts.filter(late).length}</td></tr>`;}).join('')}</tbody></table></div></section><p class="report-note">${ic('info')}Prazos em horas corridas. Aguardando usuário ou terceiros não pausa a contagem. O CSV inclui os chamados abertos no período selecionado.</p>`;}
function userRows(){return S.users.filter(u=>(u.name+' '+u.email+' '+dept(u.departmentId)).toLocaleLowerCase().includes(userQuery.toLocaleLowerCase())).map(u=>`<tr><td><div class="person-cell">${avatar(u.name)}<div><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></div></div></td><td>${esc(dept(u.departmentId))}</td><td><span class="role-badge ${u.role==='ADMIN'?'admin-role':''}">${RL[u.role]}</span></td><td><span class="badge ${u.active?'':'inactive'}">${u.active?'Ativo':'Inativo'}</span></td><td><button class="icon-button" onclick="editUser(${u.id})" aria-label="Editar ${esc(u.name)}">${ic('edit')}</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty small">Nenhuma pessoa encontrada.</div></td></tr>';}
function usersPage(){return `<section class="panel"><div class="panel-title"><div><h2>Equipe e colaboradores</h2><p>${S.users.length} pessoas cadastradas</p></div><div class="input-icon">${ic('search')}<input value="${esc(userQuery)}" oninput="userQuery=this.value;document.querySelector('#users-body').innerHTML=userRows()" placeholder="Buscar nome, e-mail ou setor" aria-label="Pesquisar pessoas"></div></div><div class="table-wrap"><table><thead><tr><th>Colaborador</th><th>Departamento</th><th>Perfil de acesso</th><th>Situação</th><th></th></tr></thead><tbody id="users-body">${userRows()}</tbody></table></div></section><div class="info-strip">${ic('shield')}<p><strong>Permissões que protegem.</strong> A aplicação Java valida todas as permissões no servidor. Esta demonstração apenas simula os perfis.</p></div>`;}
function settingsPage(){const u=current();return `<div class="settings-grid"><section class="panel settings-panel"><h2>Minha conta</h2><div class="profile-summary">${avatar(u.name,'large')}<div><h3>${esc(u.name)}</h3><p>${esc(u.email)}</p><span class="role-badge">${RL[u.role]}</span></div></div><div class="setting-line"><span>Departamento</span><strong>${esc(dept(u.departmentId))}</strong></div><div class="setting-line"><span>Aparência</span><button class="btn secondary compact" onclick="toggleTheme()">${ic(S.theme==='light'?'moon':'sun')}Tema ${S.theme==='light'?'escuro':'claro'}</button></div><div class="setting-line"><span>Perfil demonstrativo</span><button class="btn secondary compact" onclick="switchProfile()">${ic('users')}Trocar perfil</button></div></section><section class="panel settings-panel"><h2>Sobre esta demonstração</h2><p class="muted">Os dados são salvos somente neste navegador. Não existe autenticação real, servidor compartilhado ou envio de mensagens externas nesta prévia.</p><div class="sla-help"><h3>Quer utilizar com a equipe?</h3><p>A versão Angular + Java 17 + Spring Boot + PostgreSQL está nas pastas frontend e backend. Leia o README.md ou abra o arquivo COMECE-AQUI.html.</p></div><button class="btn secondary" style="margin-top:20px" onclick="resetDemo()">${ic('refresh')}Restaurar dados fictícios</button></section></div>${admin()?`<div class="settings-grid">${['departments','categories'].map(type=>`<section class="panel settings-panel"><div class="panel-title"><h2>${type==='departments'?'Departamentos':'Categorias de atendimento'}</h2><button class="icon-button" onclick="editCatalog('${type}')" aria-label="Adicionar cadastro">${ic('plus')}</button></div>${S[type].map(d=>`<div class="catalog-line"><span>${esc(d.name)}${d.active?'':' <small>(inativo)</small>'}</span><button class="icon-button" onclick="editCatalog('${type}',${d.id})" aria-label="Editar ${esc(d.name)}">${ic('edit')}</button></div>`).join('')}${type==='categories'?'<div class="sla-help"><h3>Metas em horas corridas</h3><p>Crítica: 4 h · Alta: 8 h · Média: 24 h · Baixa: 72 h</p></div>':''}</section>`).join('')}</div>`:''}`;}
function pageContent(){return ({dashboard,tickets:ticketsPage,board:boardPage,departments:departmentsPage,knowledge:knowledgePage,reports:reportsPage,users:usersPage,settings:settingsPage,assistant:assistantPage})[view]();}
function toggleNotices(){const box=$('#notices');if(box.innerHTML){box.innerHTML='';return;}const items=visible().slice(0,5);box.innerHTML=`<section class="notification-dropdown"><div class="panel-title"><h3>Notificações</h3><button class="text-button" onclick="S.readNotices=visible().map(t=>t.id);persist();render()">Marcar lidas</button></div>${items.map(t=>`<button class="notice-item ${S.readNotices.includes(t.id)?'':'unread'}" onclick="S.readNotices.push(${t.id});persist();render();openTicket(${t.id})"><span class="notice-dot"></span><div><strong>Novo chamado: ${esc(t.title)}</strong><small>${relative(t.createdAt)}</small></div>${ic('chevron')}</button>`).join('')||'<div class="empty small">Tudo em dia por aqui.</div>'}</section>`;}
function showModal(title,content,wide=false){$('#overlay').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header><div><span class="eyebrow">CHAMADO RÁPIDO</span><h2 id="modal-title">${title}</h2></div><button class="icon-button" onclick="closeModal()" aria-label="Fechar formulário">${ic('close')}</button></header>${content}</section></div>`;document.body.style.overflow='hidden';focusModal();}
function closeModal(){detailId=null;$('#overlay').innerHTML='';document.body.style.overflow='';}
function focusModal(){setTimeout(()=>{$('#overlay input:not([type=file]),#overlay textarea,#overlay select,#overlay button')?.focus();},40);}
function formFooter(label='Salvar'){return `<footer><button class="btn secondary" type="button" onclick="closeModal()">Cancelar</button><button class="btn primary" type="submit">${label}${ic('check')}</button></footer>`;}
function newTicket(fromTriage=false){const u=current();showModal('Como podemos ajudar?',`<form onsubmit="submitNewTicket(event,${fromTriage})"><div class="new-ticket-layout"><div><label for="title">O que aconteceu? *</label><input id="title" name="title" minlength="5" maxlength="180" required placeholder="Ex.: Não consigo acessar o sistema de cobrança" value="${fromTriage?esc('Suporte: '+TRIAGE_CATEGORIES.find(c=>c.id===triage.category)?.title):''}"><div class="form-grid"><div><label for="category">Categoria *</label><select id="category" name="categoryId" required>${selectOptions(S.categories.filter(c=>c.active).map(c=>[c.id,c.name]),'','Selecione uma categoria')}</select></div><div><label for="priority">Impacto / prioridade *</label><select id="priority" name="priority">${selectOptions([['BAIXA','Baixa - sem interrupção'],['MEDIA','Média - consigo continuar'],['ALTA','Alta - trabalho impedido'],['CRITICA','Crítica - várias pessoas paradas']],'MEDIA')}</select></div></div><label for="description">Conte um pouco mais *</label><textarea id="description" name="description" minlength="15" maxlength="12000" rows="5" required placeholder="Quando começou? Qual mensagem aparece? O que você já tentou?"></textarea><div class="form-grid"><div><label for="location">Localização</label><input id="location" name="location" maxlength="120" placeholder="Sala, andar ou estação"></div><div><label for="equipment">Equipamento / patrimônio</label><input id="equipment" name="equipment" maxlength="120" placeholder="Ex.: PC-024"></div></div><label for="contact">Ramal ou contato interno</label><input id="contact" name="contact" maxlength="80" placeholder="Como a TI pode falar com você?"><label class="upload-zone">${ic('upload')}<strong>Clique para adicionar arquivos</strong><span>PNG, JPG, PDF ou TXT · até 5 arquivos de 5 MB</span><input name="files" type="file" multiple accept=".png,.jpg,.jpeg,.pdf,.txt" onchange="document.querySelector('#selected-files').textContent=[...this.files].map(f=>f.name).join(', ')"></label><small id="selected-files" class="field-help"></small></div><aside class="new-ticket-guide"><span class="guide-icon">${ic('ticket')}</span><h3>Um bom relato acelera a solução.</h3><p>Seja específico e informe o impacto do problema no seu trabalho.</p><div class="requester-info"><small>SOLICITANTE</small><strong>${esc(u.name)}</strong><small>DEPARTAMENTO</small><strong>${esc(dept(u.departmentId))}</strong></div><div class="privacy-note">${ic('shield')}<p>Nunca inclua senhas, códigos de acesso ou dados pessoais de clientes.</p></div>${fromTriage?`<div class="triage-note">${ic('checkCircle')}O resumo do assistente acompanhará o chamado.</div>`:''}<small>* Campos obrigatórios</small></aside></div>${formFooter('Enviar chamado')}</form>`,true);}
function readFile(file){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({id:Date.now()+Math.random(),name:file.name,size:file.size,mime:file.type||'application/octet-stream',data:reader.result});reader.onerror=reject;reader.readAsDataURL(file);});}
function filesValid(files){return files.length<=5&&files.every(f=>f.size<=5*1024*1024&&/\.(png|jpg|jpeg|pdf|txt)$/i.test(f.name));}
async function submitNewTicket(event,fromTriage){event.preventDefault();const form=event.target,f=new FormData(form),title=String(f.get('title')).trim(),description=String(f.get('description')).trim();if(title.length<5||description.length<15){notify('Descreva o problema com mais detalhes.',true);return;}if(!S.departments.find(d=>d.id===current().departmentId)?.active){notify('Seu departamento está inativo.',true);return;}const files=[...form.querySelector('[name=files]').files];if(!filesValid(files)){notify('Use até 5 arquivos PNG, JPG, PDF ou TXT de até 5 MB.',true);return;}const submit=form.querySelector('button[type=submit]');submit.disabled=true;try{const attachments=await Promise.all(files.map(readFile)),now=new Date().toISOString(),p=String(f.get('priority'));const t={id:Math.max(0,...S.tickets.map(t=>t.id))+1,title,description:description+(fromTriage?'\n\n--- Resumo do assistente ---\n'+triage.messages.map(m=>(m.side==='bot'?'Assistente: ':'Usuário: ')+m.text).join('\n'):''),requesterId:current().id,departmentId:current().departmentId,categoryId:Number(f.get('categoryId')),priority:p,status:'ABERTO',assigneeId:null,createdAt:now,updatedAt:now,dueAt:new Date(Date.now()+HOURS[p]*3600000).toISOString(),resolvedAt:null,solution:'',rating:null,location:String(f.get('location')),equipment:String(f.get('equipment')),contact:String(f.get('contact')),comments:[],history:[{action:'Chamado aberto',details:'Solicitação registrada para '+dept(current().departmentId),actor:current().name,createdAt:now}],attachments};S.tickets.unshift(t);if(fromTriage)triage.ticketId=t.id;persist();closeModal();render();openTicket(t.id);notify(protocol(t)+' registrado nesta demonstração.');}catch{notify('Não foi possível ler o anexo.',true);submit.disabled=false;}}
function allowed(t){return TRANS[t.status].filter(s=>staff()||t.status==='ABERTO'&&s==='CANCELADO'||t.status==='RESOLVIDO'&&['FECHADO','EM_ANDAMENTO'].includes(s));}
function openTicket(id){const t=visible().find(t=>t.id===Number(id));if(!t){notify('Chamado não encontrado para este perfil.',true);return;}detailId=t.id;renderDetail();document.body.style.overflow='hidden';focusModal();}
function renderDetail(){const t=visible().find(t=>t.id===detailId);if(!t)return;const requester=user(t.requesterId),comments=t.comments.filter(c=>staff()||!c.internal);const internal=staff();
 $('#overlay').innerHTML=`<div class="drawer-backdrop" onclick="if(event.target===this)closeModal()"><section class="detail-drawer" role="dialog" aria-modal="true" aria-labelledby="detail-title"><header class="drawer-header"><div><span class="eyebrow">${protocol(t)}</span><h2 id="detail-title">${esc(t.title)}</h2></div><button class="icon-button" onclick="closeModal()" aria-label="Fechar chamado">${ic('close')}</button></header><div class="detail-badges">${status(t)}${priority(t)}<span class="deadline ${late(t)?'danger':''}">${ic('clock')}${deadline(t)}</span></div><div class="detail-grid"><div class="detail-main"><section class="detail-description"><h3>Sobre a solicitação</h3><p class="preserve">${esc(t.description)}</p><div class="detail-mini-grid"><div><small>LOCALIZAÇÃO</small><strong>${esc(t.location||'Não informada')}</strong></div><div><small>EQUIPAMENTO</small><strong>${esc(t.equipment||'Não informado')}</strong></div><div><small>CONTATO / RAMAL</small><strong>${esc(t.contact||'Não informado')}</strong></div><div><small>CATEGORIA</small><strong>${esc(cat(t.categoryId))}</strong></div></div></section>${t.solution?`<div class="solution-box"><h3>${ic('checkCircle')}Solução registrada</h3><p class="preserve">${esc(t.solution)}</p></div>`:''}<section class="detail-attachments"><h3>${ic('paperclip')}Anexos <span class="count">${t.attachments.length}/5</span></h3>${t.attachments.map((a,i)=>`<button class="attachment-file" onclick="downloadAttachment(${i})">${ic('file')}<span>${esc(a.name)}<small>${Math.round(a.size/1024)} KB</small></span>${ic('download')}</button>`).join('')}${!terminal(t)&&t.attachments.length<5?`<label class="attach-button">${ic('plus')}Adicionar arquivo<input type="file" accept=".png,.jpg,.jpeg,.pdf,.txt" onchange="attachFile(this)"></label>`:''}<small class="muted">PNG, JPG, PDF ou TXT. Até 5 MB por arquivo.</small></section><div class="detail-tabs"><button class="${detailTab==='conversation'?'active':''}" onclick="detailTab='conversation';renderDetail()">Conversa <span class="count">${comments.length}</span></button><button class="${detailTab==='history'?'active':''}" onclick="detailTab='history';renderDetail()">Histórico</button></div>${detailTab==='conversation'?`<div class="comments">${comments.map(c=>`<article class="comment ${c.internal?'internal':''}">${avatar(user(c.authorId)?.name||'Usuário','small')}<div><header><strong>${esc(user(c.authorId)?.name||'Usuário')}</strong><time>${date(c.createdAt)}</time></header>${c.internal?`<span class="internal-label">${ic('lock')}Nota interna · visível somente para TI</span>`:''}<p>${esc(c.body)}</p></div></article>`).join('')||`<div class="empty small">${ic('chat')}<p>A conversa sobre este chamado começa aqui.</p></div>`}</div>${!['FECHADO','CANCELADO'].includes(t.status)?`<form class="comment-form" onsubmit="sendComment(event)"><textarea name="body" minlength="2" maxlength="6000" required rows="3" placeholder="Escreva uma mensagem. Não compartilhe senhas." aria-label="Nova mensagem"></textarea><div>${staff()?'<label class="checkbox"><input name="internal" type="checkbox">Nota interna</label>':''}<button class="btn primary compact" type="submit">Enviar${ic('send')}</button></div></form>`:''}`:`<div class="history-list">${t.history.filter(h=>staff()||h.action!=='Nota interna').map(h=>`<article><i></i><div><strong>${esc(h.action)}</strong><p>${esc(h.details)}</p><small>${esc(h.actor)} · ${date(h.createdAt)}</small></div></article>`).join('')}</div>`}</div><aside class="detail-sidebar"><section><h3>Informações do chamado</h3><div class="person-cell">${avatar(requester.name)}<div><strong>${esc(requester.name)}</strong><small>Solicitante</small></div></div><dl><dt>Departamento</dt><dd>${esc(dept(t.departmentId))}</dd><dt>Aberto em</dt><dd>${date(t.createdAt)}</dd><dt>Prazo de solução</dt><dd class="${late(t)?'danger':''}">${date(t.dueAt)}</dd><dt>Responsável</dt><dd>${esc(user(t.assigneeId)?.name||'Aguardando atribuição')}</dd></dl></section><form class="detail-controls" onsubmit="saveTicket(event)"><h3>Próximo passo</h3>${staff()&&!terminal(t)?`<button class="btn secondary full" type="button" onclick="assumeTicket()">${ic('users')}Assumir chamado</button><label for="edit-assignee">Responsável</label><select id="edit-assignee" name="assigneeId">${selectOptions(S.users.filter(u=>u.role!=='COLABORADOR'&&u.active).map(u=>[u.id,u.name]),t.assigneeId,'Não atribuído')}</select><label for="edit-priority">Prioridade</label><select id="edit-priority" name="priority">${selectOptions(Object.entries(PL),t.priority)}</select>`:''}<label for="edit-status">Status</label><select id="edit-status" name="status" onchange="detailFields()">${selectOptions([t.status,...allowed(t)].map(s=>[s,LABEL[s]]),t.status)}</select><div id="detail-fields"></div><button class="btn primary full" type="submit" ${!allowed(t).length&&terminal(t)?'disabled':''}>Salvar alterações</button></form>${t.requesterId===current().id&&['RESOLVIDO','FECHADO'].includes(t.status)?`<section class="rating-box"><h3>Como foi o atendimento?</h3><div>${[1,2,3,4,5].map(n=>`<button onclick="rateTicket(${n})" class="${n<=(t.rating||0)?'filled':''}" aria-label="Avaliar com ${n} estrela(s)">${ic('star')}</button>`).join('')}</div><small>Sua avaliação ajuda a melhorar.</small></section>`:''}</aside></div></section></div>`;
}
function history(t,action,details){t.history.push({action,details,actor:current().name,createdAt:new Date().toISOString()});}
function detailFields(){const t=S.tickets.find(t=>t.id===detailId),s=$('#edit-status').value;$('#detail-fields').innerHTML=(s==='RESOLVIDO'&&t.status!=='RESOLVIDO'?'<label for="solution">Solução aplicada *</label><textarea id="solution" name="solution" rows="4" minlength="10" maxlength="12000" required placeholder="Descreva a solução..."></textarea>':'')+(s==='CANCELADO'||['RESOLVIDO','FECHADO'].includes(t.status)&&s==='EM_ANDAMENTO'?'<label for="reason">Justificativa *</label><textarea id="reason" name="reason" rows="3" minlength="10" maxlength="1000" required></textarea>':'');}
function saveTicket(event){event.preventDefault();const t=visible().find(t=>t.id===detailId),f=new FormData(event.target),s=String(f.get('status'));if(!t)return;if(s!==t.status&&!allowed(t).includes(s)){notify('Transição não permitida.',true);return;}const reopen=['RESOLVIDO','FECHADO'].includes(t.status)&&s==='EM_ANDAMENTO';if((s==='CANCELADO'&&s!==t.status||reopen)&&String(f.get('reason')||'').trim().length<10){notify('Informe uma justificativa com pelo menos 10 caracteres.',true);return;}if(s==='RESOLVIDO'&&t.status!==s&&String(f.get('solution')||'').trim().length<10){notify('Descreva a solução em pelo menos 10 caracteres.',true);return;}if(staff()&&!terminal(t)){const p=String(f.get('priority'));if(p&&p!==t.priority){t.priority=p;t.dueAt=new Date(Date.parse(t.slaStartedAt||t.createdAt)+HOURS[p]*3600000).toISOString();history(t,'Prioridade alterada',PL[p]);}const a=Number(f.get('assigneeId'))||null;if(a!==t.assigneeId){t.assigneeId=a;history(t,'Responsável atualizado',user(a)?.name||'Devolvido à fila');}}if(s!==t.status){const old=t.status;t.status=s;if(s==='RESOLVIDO'){t.solution=String(f.get('solution')).trim();t.resolvedAt=new Date().toISOString();}if(s==='EM_ANDAMENTO'&&!t.assigneeId&&staff())t.assigneeId=current().id;if(reopen){t.resolvedAt=null;t.rating=null;t.slaStartedAt=new Date().toISOString();t.dueAt=new Date(Date.now()+HOURS[t.priority]*3600000).toISOString();}history(t,reopen?'Chamado reaberto':'Status atualizado',LABEL[old]+' -> '+LABEL[s]+(f.get('reason')?'. '+f.get('reason'):''));}t.updatedAt=new Date().toISOString();persist();render();renderDetail();notify('Chamado atualizado nesta demonstração.');}
function assumeTicket(){if(!staff())return;$('#edit-assignee').value=String(current().id);if($('#edit-status').value==='ABERTO')$('#edit-status').value='EM_ANDAMENTO';$('#edit-status').form.requestSubmit();}
function sendComment(event){event.preventDefault();const t=visible().find(t=>t.id===detailId),f=new FormData(event.target),body=String(f.get('body')||'').trim();if(!t||body.length<2)return;const internal=staff()&&f.get('internal')==='on';t.comments.push({authorId:current().id,body,internal,createdAt:new Date().toISOString()});history(t,internal?'Nota interna':'Mensagem enviada',internal?'Registro exclusivo da equipe de TI.':'Nova mensagem na conversa.');persist();renderDetail();notify(internal?'Nota interna registrada.':'Mensagem enviada.');}
async function attachFile(input){const file=input.files?.[0],t=visible().find(t=>t.id===detailId);if(!file||!t)return;if(t.attachments.length>=5||!filesValid([file])){notify('Use até 5 anexos permitidos de até 5 MB.',true);return;}try{t.attachments.push(await readFile(file));history(t,'Arquivo anexado',file.name);persist();renderDetail();notify('Arquivo salvo neste navegador.');}catch{notify('Não foi possível ler o arquivo.',true);}}
function downloadAttachment(index){const a=visible().find(t=>t.id===detailId)?.attachments[index];if(!a?.data)return;const link=document.createElement('a');link.href=a.data;link.download=a.name;link.click();}
function rateTicket(rating){const t=visible().find(t=>t.id===detailId);if(t?.requesterId!==current().id)return;t.rating=rating;history(t,'Atendimento avaliado',rating+' de 5 estrelas');persist();render();renderDetail();notify('Obrigada pela sua avaliação!');}
function openArticle(id){const a=S.articles.find(a=>a.id===id);if(!a)return;showModal(a.title,`<article class="article-reader"><p class="lead">${esc(a.excerpt)}</p><div class="article-content preserve">${esc(a.body)}</div><footer><span>${esc(a.category)} · ${date(a.updatedAt)}</span>${admin()?`<button class="btn secondary compact" onclick="editArticle(${a.id})">${ic('edit')}Editar</button>`:''}<button class="btn primary compact" onclick="newTicket()">Ainda preciso de ajuda</button></footer></article>`);}
function editArticle(id){if(!admin())return;const a=S.articles.find(a=>a.id===id)||{title:'',excerpt:'',body:'',category:'Boas práticas',active:true};showModal(id?'Editar artigo':'Novo artigo',`<form class="simple-form" onsubmit="saveArticle(event,${id||0})"><label for="article-title">Título *</label><input id="article-title" name="title" value="${esc(a.title)}" minlength="5" maxlength="180" required><label for="article-category">Categoria *</label><input id="article-category" name="category" value="${esc(a.category)}" maxlength="80" required><label for="article-excerpt">Resumo *</label><textarea id="article-excerpt" name="excerpt" rows="2" maxlength="300" required>${esc(a.excerpt)}</textarea><label for="article-body">Conteúdo (texto simples) *</label><textarea id="article-body" name="body" rows="8" minlength="20" maxlength="12000" required>${esc(a.body)}</textarea><label class="checkbox"><input type="checkbox" name="active" ${a.active?'checked':''}>Publicado e visível para colaboradores</label>${formFooter('Salvar artigo')}</form>`);}
function saveArticle(event,id){event.preventDefault();if(!admin())return;const f=new FormData(event.target),a=S.articles.find(a=>a.id===id)||{id:Math.max(0,...S.articles.map(a=>a.id))+1};for(const key of ['title','category','excerpt','body'])a[key]=String(f.get(key)||'').trim();a.active=f.get('active')==='on';a.updatedAt=new Date().toISOString();if(!id)S.articles.unshift(a);persist();closeModal();render();notify('Artigo salvo.');}
function editUser(id){if(!admin())return;const u=user(id)||{name:'',email:'',departmentId:'',role:'COLABORADOR',active:true};showModal(id?'Editar pessoa':'Adicionar pessoa',`<form class="simple-form" onsubmit="saveUser(event,${id||0})"><label for="person-name">Nome completo *</label><input id="person-name" name="name" value="${esc(u.name)}" minlength="2" maxlength="100" required><label for="person-email">E-mail *</label><input id="person-email" name="email" type="email" value="${esc(u.email)}" maxlength="180" required><div class="form-grid"><div><label for="person-department">Departamento *</label><select id="person-department" name="departmentId" required>${selectOptions(S.departments.filter(d=>d.active).map(d=>[d.id,d.name]),u.departmentId,'Selecione')}</select></div><div><label for="person-role">Perfil *</label><select id="person-role" name="role">${selectOptions(Object.entries(RL),u.role)}</select></div></div><label class="checkbox"><input type="checkbox" name="active" ${u.active?'checked':''}>Usuário ativo</label><p class="field-help">Nesta demonstração não são armazenadas senhas. A aplicação Java inclui senha temporária e troca obrigatória.</p>${formFooter('Salvar pessoa')}</form>`);}
function saveUser(event,id){event.preventDefault();if(!admin())return;const f=new FormData(event.target),email=String(f.get('email')).trim().toLowerCase();if(S.users.some(u=>u.email===email&&u.id!==id)){notify('Este e-mail já está cadastrado.',true);return;}if(id===current().id&&(f.get('role')!=='ADMIN'||f.get('active')!=='on')){notify('Não desative ou rebaixe sua própria conta.',true);return;}const u=user(id)||{id:Math.max(...S.users.map(u=>u.id))+1};Object.assign(u,{name:String(f.get('name')).trim(),email,role:String(f.get('role')),departmentId:Number(f.get('departmentId')),active:f.get('active')==='on'});if(!id)S.users.push(u);persist();closeModal();render();notify('Pessoa salva nesta demonstração.');}
function editCatalog(type,id){if(!admin()||!['departments','categories'].includes(type))return;const c=S[type].find(c=>c.id===id)||{name:'',active:true};showModal(type==='departments'?'Cadastro de departamento':'Cadastro de categoria',`<form class="simple-form" onsubmit="saveCatalog(event,'${type}',${id||0})"><label for="catalog-name">Nome *</label><input id="catalog-name" name="name" value="${esc(c.name)}" minlength="2" maxlength="80" required><label class="checkbox"><input name="active" type="checkbox" ${c.active?'checked':''}>Ativo</label><p class="field-help">Inativar preserva o histórico dos chamados existentes.</p>${formFooter('Salvar cadastro')}</form>`);}
function saveCatalog(event,type,id){event.preventDefault();if(!admin())return;const f=new FormData(event.target),name=String(f.get('name')).trim();if(S[type].some(c=>c.id!==id&&c.name.toLocaleLowerCase()===name.toLocaleLowerCase())){notify('Este nome já está cadastrado.',true);return;}const c=S[type].find(c=>c.id===id)||{id:Math.max(...S[type].map(c=>c.id))+1};c.name=name;c.active=f.get('active')==='on';if(!id)S[type].push(c);persist();closeModal();render();notify('Cadastro salvo.');}
function switchProfile(){showModal('Explore outro ponto de vista',`<form class="simple-form" onsubmit="event.preventDefault();S.userId=Number(new FormData(this).get('profile'));persist();closeModal();filter={q:'',status:'',priority:'',department:'',overdue:false,mine:false};page=0;triage=null;navigate('dashboard');notify('Perfil demonstrativo alterado.')"><p class="field-help" style="margin-top:20px">Troca livre de perfil apenas nesta prévia offline. No sistema Java cada usuário entra com sua própria senha.</p><label for="profile">Perfil da demonstração</label><select id="profile" name="profile">${selectOptions(S.users.filter(u=>u.active).map(u=>[u.id,u.name+' - '+RL[u.role]+' / '+dept(u.departmentId)]),S.userId)}</select>${formFooter('Explorar perfil')}</form>`);}
function resetDemo(){if(!confirm('Restaurar os dados fictícios? As alterações desta demonstração serão apagadas.'))return;S=seed();persist();filter={q:'',status:'',priority:'',department:'',overdue:false,mine:false};triage=null;page=0;navigate('dashboard');notify('Demonstração restaurada.');}
function exportReport(){if(!staff())return;const safe=v=>{v=String(v??'');if(/^[=+@\-]/.test(v.trimStart())||/^[\t\r\n]/.test(v))v="'"+v;return '"'+v.replace(/"/g,'""')+'"';};const rows=[['Protocolo','Titulo','Departamento','Solicitante','Responsavel','Categoria','Prioridade','Status','Abertura','Prazo','Resolucao','Nota'],...summaries().all.map(t=>[protocol(t),t.title,dept(t.departmentId),user(t.requesterId).name,user(t.assigneeId)?.name||'',cat(t.categoryId),PL[t.priority],LABEL[t.status],t.createdAt,t.dueAt,t.resolvedAt||'',t.rating||''])];const blob=new Blob(['﻿'+rows.map(row=>row.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Chamado-Rapido-demonstracao.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV da demonstração exportado.');}
const TRIAGE_CATEGORIES=[{id:'rede',icon:'wifi',title:'Rede e internet',desc:'Problemas de conexão'},{id:'impressora',icon:'printer',title:'Impressoras',desc:'Falhas na impressão'},{id:'acesso',icon:'lock',title:'Sistemas e acessos',desc:'Dificuldades para entrar'},{id:'computador',icon:'monitor',title:'Computador',desc:'Lentidão ou falhas'}];
const STEPS={
 rede:{message:'Vamos verificar a conexão. Outros computadores do setor também estão sem internet?',options:[['Sim, mais pessoas estão sem internet','escalar'],['Não, apenas o meu','rede_cabo']]},
 rede_cabo:{message:'Verifique apenas o encaixe do cabo externo de rede ou se o Wi-Fi está conectado. Não altere instalações elétricas nem reinicie equipamentos compartilhados. A conexão voltou?',options:[['Sim, voltou a funcionar','resolvido'],['Ainda estou sem conexão','escalar']]},
 impressora:{message:'A impressora está ligada e mostra alguma mensagem no visor?',options:[['Existe um erro no visor','escalar'],['Está ligada e sem mensagens','impressora_fila'],['Não está ligando','escalar']]},
 impressora_fila:{message:'Confira a impressora selecionada e se há papel na bandeja. Não desmonte o equipamento. Conseguiu imprimir?',options:[['Sim, consegui imprimir','resolvido'],['Ainda não consegui','escalar']]},
 acesso:{message:'Confira o usuário, Caps Lock e o endereço do sistema. Nunca compartilhe sua senha. Após verificar, o acesso funcionou?',options:[['Sim, consegui acessar','resolvido'],['Preciso de ajuda com o acesso','escalar']]},
 computador:{message:'Há cheiro de queimado, fumaça, faíscas ou aquecimento anormal?',options:[['Sim, há um sinal de risco','risco'],['Não, mas apresenta falhas','computador_lento']]},
 computador_lento:{message:'Salve seus documentos e feche programas que não está usando. Não desligue servidores ou equipamentos compartilhados. Isso melhorou o funcionamento?',options:[['Sim, melhorou','resolvido'],['O problema continua','escalar']]},
 risco:{message:'Interrompa o uso e afaste-se do equipamento. Não abra o gabinete nem toque em fios. Avise imediatamente a TI ou a equipe de emergência responsável. O chamado não substitui o atendimento emergencial.',result:'ENCAMINHADO'},
 escalar:{message:'Vamos encaminhar para a equipe de TI. O resumo desta conversa acompanhará seu chamado, para você não precisar repetir tudo.',result:'ENCAMINHADO'},
 resolvido:{message:'Que bom! A orientação resolveu seu problema. Se precisar novamente, estamos por aqui.',result:'RESOLVIDO'}
};
function startTriage(id){const node=STEPS[id];if(!node)return;triage={category:id,node:id,messages:[{side:'bot',text:node.message}],ticketId:null};render();}
function answerTriage(index){if(!triage)return;const option=STEPS[triage.node].options?.[index];if(!option)return;triage.messages.push({side:'user',text:option[0]},{side:'bot',text:STEPS[option[1]].message});triage.node=option[1];render();}
function assistantPage(){const step=triage?STEPS[triage.node]:null;return `<div class="assistant-layout"><section class="panel assistant-chat"><header class="assistant-header"><span class="bot-avatar"><img src="assets/mascote.png" alt=""></span><div><h2>Assistente Rápido</h2><p><span class="live-dot"></span>Triagem guiada · orientações seguras</p></div>${triage?`<button class="icon-button" onclick="triage=null;render()" title="Nova conversa" aria-label="Nova conversa">${ic('refresh')}</button>`:''}</header><div class="chat-body" aria-live="polite">${!triage?`<div class="bot-welcome"><span class="bot-wave">${ic('chat')}</span><h2>Olá, ${esc(current().name.split(' ')[0])}! Como posso ajudar?</h2><p>Escolha o assunto. Vou fazer algumas perguntas para entender o que está acontecendo.</p></div><div class="triage-categories">${TRIAGE_CATEGORIES.map(c=>`<button onclick="startTriage('${c.id}')">${ic(c.icon)}<strong>${c.title}</strong><small>${c.desc}</small>${ic('chevron')}</button>`).join('')}</div>`:triage.messages.map(m=>`<div class="chat-message ${m.side==='user'?'from-user':''}">${m.side==='bot'?`<span class="chat-bot-mark">${ic('bolt')}</span>`:''}<p>${esc(m.text)}</p></div>`).join('')+`<div class="chat-options">${(step.options||[]).map((o,i)=>`<button class="btn secondary" onclick="answerTriage(${i})">${o[0]}${ic('arrow')}</button>`).join('')}</div>`+(step.result==='ENCAMINHADO'&&!triage.ticketId?`<div class="chat-result">${ic('ticket')}<strong>Vamos levar isso para a equipe de TI.</strong><p>As verificações feitas aqui acompanharão sua solicitação.</p><button class="btn primary" onclick="newTicket(true)">Abrir chamado com o resumo${ic('arrow')}</button></div>`:'')+(step.result==='RESOLVIDO'?`<div class="chat-result success-result">${ic('checkCircle')}<strong>Problema resolvido, dia seguindo!</strong><p>Nesta demonstração, a conversa fica apenas na sessão atual.</p><button class="btn secondary" onclick="triage=null;render()">Iniciar outra conversa</button></div>`:'')+(triage.ticketId?`<button class="btn primary" onclick="openTicket(${triage.ticketId})">Acompanhar chamado criado${ic('arrow')}</button>`:'')}</div><footer class="assistant-footer">${ic('shield')}Nunca informe sua senha. Este assistente usa fluxos predefinidos, não IA generativa.</footer></section><aside class="assistant-info"><div class="panel"><span class="stat-icon gold">${ic('bolt')}</span><h3>Tecnologia com acolhimento.</h3><p>Se a orientação não resolver, a equipe humana de TI assume o atendimento.</p><hr><strong>Prefere falar com a TI?</strong><p>Você pode abrir um chamado a qualquer momento.</p><button class="btn secondary full" onclick="newTicket()">Abrir chamado diretamente</button></div><div class="safety-note">${ic('alert')}<p>Risco elétrico, fumaça ou cheiro de queimado? Interrompa o uso e avise a equipe responsável. Não manipule o equipamento.</p></div></aside></div>`;}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(PAGES[next]&&next!==view){view=next;render();}});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){closeModal();const n=$('#notices');if(n)n.innerHTML='';$('.sidebar')?.classList.remove('open');$('.sidebar-scrim')?.remove();}if(event.key==='Tab'&&$('#overlay').innerHTML){const dialog=$('#overlay [role=dialog]');const nodes=[...dialog.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href]')].filter(e=>e.offsetParent!==null);const first=nodes[0],last=nodes[nodes.length-1];if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first?.focus();}}});
render();
